-- 004_schema_v2.sql
-- Schema v2: fragment_label/text, rarity, is_skippable, exploration_narrative, sealed_story

-- ─── 1. Clear player content ─────────────────────────────────────────────────
DELETE FROM creature_pages;
DELETE FROM fragments;
UPDATE notebooks SET status = 'active', story_id = NULL, sealed_at = NULL WHERE status = 'sealed';

-- ─── 2. Clear game content ───────────────────────────────────────────────────
DELETE FROM scene_options;
DELETE FROM fragment_scenes;
DELETE FROM fragment_atmosphere;
DELETE FROM exploration_nodes;
DELETE FROM story_fragments;
DELETE FROM stories;

-- ─── 3. Schema alterations ───────────────────────────────────────────────────

-- stories: change difficulty, add narrative columns
ALTER TABLE stories DROP CONSTRAINT IF EXISTS stories_difficulty_check;
ALTER TABLE stories ADD CONSTRAINT stories_difficulty_check
  CHECK (difficulty IN ('normal','rare','legendary'));
ALTER TABLE stories
  ADD COLUMN IF NOT EXISTS sealed_narrative TEXT,
  ADD COLUMN IF NOT EXISTS lore_narrative   TEXT;

-- story_fragments: new column structure
ALTER TABLE story_fragments DROP CONSTRAINT IF EXISTS story_fragments_layer_check;
ALTER TABLE story_fragments DROP CONSTRAINT IF EXISTS story_fragments_difficulty_check;
ALTER TABLE story_fragments DROP COLUMN IF EXISTS text;
ALTER TABLE story_fragments DROP COLUMN IF EXISTS difficulty;
ALTER TABLE story_fragments
  ADD COLUMN IF NOT EXISTS rarity         TEXT NOT NULL DEFAULT 'common',
  ADD COLUMN IF NOT EXISTS fragment_label TEXT NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS fragment_text  TEXT NOT NULL DEFAULT '';
ALTER TABLE story_fragments ADD CONSTRAINT story_fragments_layer_check
  CHECK (layer IN ('basic','lore'));
ALTER TABLE story_fragments ADD CONSTRAINT story_fragments_rarity_check
  CHECK (rarity IN ('common','rare'));
ALTER TABLE story_fragments ALTER COLUMN rarity         DROP DEFAULT;
ALTER TABLE story_fragments ALTER COLUMN fragment_label DROP DEFAULT;
ALTER TABLE story_fragments ALTER COLUMN fragment_text  DROP DEFAULT;

-- fragment_scenes: add is_skippable
ALTER TABLE fragment_scenes
  ADD COLUMN IF NOT EXISTS is_skippable BOOLEAN NOT NULL DEFAULT false;

-- fragments (player-held): add exploration_narrative
ALTER TABLE fragments
  ADD COLUMN IF NOT EXISTS exploration_narrative TEXT;

-- notebooks: add sealed_story
ALTER TABLE notebooks
  ADD COLUMN IF NOT EXISTS sealed_story TEXT;

-- creature_pages: update layer constraint
ALTER TABLE creature_pages DROP CONSTRAINT IF EXISTS creature_pages_unlocked_layer_check;
ALTER TABLE creature_pages ADD CONSTRAINT creature_pages_unlocked_layer_check
  CHECK (unlocked_layer IN ('basic','lore'));

