INSERT INTO stories (id, title, difficulty, creature_type, creature_description, sealed_narrative, lore_narrative)
INSERT INTO story_fragments (id, story_id, layer, rarity, fragment_label, fragment_text, time_condition, weather_condition, date_condition, motif_tags, is_user_submitted)
INSERT INTO fragment_atmosphere (id, story_fragment_id, atmosphere_text) VALUES
('d0001001-0000-0000-0000-000000000001','b0000001-0000-0000-0000-000000000001','門推開的瞬間，一股說不清的氣味湧出來。不是黴味，不是灰塵，而是某種更安靜的東西——像是什麼東西在這裡慢慢消失了很久，久到空氣都記住了它的形狀。窗簾拉得死緊，光線只從布縫裡滲進來。'),
('d0001002-0000-0000-0000-000000000001','b0000001-0000-0000-0000-000000000001','這個房間的空氣和外面不一樣。不是溫度，是某種密度。我聞到了什麼，熟悉又說不清楚，像是很久以前養過的什麼東西留下的氣息。窗簾沒有動，但我感覺有什麼在注意我。'),
('d0001003-0000-0000-0000-000000000001','b0000001-0000-0000-0000-000000000001','我沒有開燈。黑暗裡有一種氣味，在某個地方待了很久、最後離開之後留下的那種。這個房間很久沒有人進來了，但感覺不像是空的。');
INSERT INTO fragment_scenes (id, story_fragment_id, layer_index, atmosphere_text, is_skippable) VALUES
('e0001101-0000-0000-0000-000000000001','b0000001-0000-0000-0000-000000000001',1,'我站在門口。房間不大，但走進去需要某種決心。地板上有幾個淺淡的痕跡，從門口延伸向房間深處。',true),
('e0001102-0000-0000-0000-000000000001','b0000001-0000-0000-0000-000000000001',1,'牆角有個東西的輪廓，我看不清楚。那個氣味從那個方向來，有點像木屑，有點像什麼東西乾掉之後的味道。',true),
('e0001103-0000-0000-0000-000000000001','b0000001-0000-0000-0000-000000000001',1,'我的眼睛開始適應黑暗。窗簾縫隙透進一條細細的光，落在地板上。灰塵的移動方向不對——它往上飄，不是往下沉。',true),
('e0001201-0000-0000-0000-000000000001','b0000001-0000-0000-0000-000000000001',2,'我已經很近了。那個氣味在這裡最濃，像是中心點。地板上有什麼，非常細小，我蹲下來才看得清楚。',false),
('e0001202-0000-0000-0000-000000000001','b0000001-0000-0000-0000-000000000001',2,'我站在房間中央。眼睛完全適應了黑暗。我看見了房間的質地，某種說不清楚的存在感從角落蔓延過來。',false),
('e0001203-0000-0000-0000-000000000001','b0000001-0000-0000-0000-000000000001',2,'我感覺到了什麼，不是看見，是感覺到。有一個極輕的重量，像是有什麼東西在決定要不要靠近我。',false),
('e0001301-0000-0000-0000-000000000001','b0000001-0000-0000-0000-000000000001',3,'我看見了。不是完整地看見，是某種片刻的清晰——這個房間曾經有什麼在這裡生活過，而它沒有真正離開。',false),
('e0001302-0000-0000-0000-000000000001','b0000001-0000-0000-0000-000000000001',3,'那個氣味達到了頂點。我的手還放在地板上，我感覺到了——某個地方比其他地方稍微暖一點點。',false),
('e0001303-0000-0000-0000-000000000001','b0000001-0000-0000-0000-000000000001',3,'我屏住呼吸。有什麼聲音，極輕，像爪子在某個表面非常緩慢地移動。然後停了。然後又開始。',false);
INSERT INTO scene_options (id, scene_id, text, is_correct, fail_text) VALUES
('f0011101-0000-0000-0000-000000000001','e0001101-0000-0000-0000-000000000001','站在原地，等眼睛完全適應黑暗',true,''),
('f0011102-0000-0000-0000-000000000001','e0001101-0000-0000-0000-000000000001','沿著痕跡的邊緣慢慢往裡移動',true,''),
('f0011103-0000-0000-0000-000000000001','e0001101-0000-0000-0000-000000000001','跟著地板的痕跡直接走進去',true,''),
('f0011201-0000-0000-0000-000000000001','e0001201-0000-0000-0000-000000000001','靜止不動，讓感知繼續擴散',true,''),
('f0011202-0000-0000-0000-000000000001','e0001201-0000-0000-0000-000000000001','輕輕把手放在地板上',true,''),
('f0011203-0000-0000-0000-000000000001','e0001201-0000-0000-0000-000000000001','用手機手電筒照向那個角落',false,'強光照過去。那個氣味在光線觸碰的瞬間消失了。'),
('f0011204-0000-0000-0000-000000000001','e0001201-0000-0000-0000-000000000001','開口說話',false,'你的聲音在房間裡顯得很突兀。那個感覺在你說話的瞬間消失了。'),
('f0011205-0000-0000-0000-000000000001','e0001201-0000-0000-0000-000000000001','站起來，環顧整個房間',false,'你移動了。就在你站起來的瞬間，那個感覺消失了。'),
('f0011206-0000-0000-0000-000000000001','e0001201-0000-0000-0000-000000000001','伸手去摸那個輪廓',false,'你的手指碰到了什麼，極輕，像碰到了灰塵。然後什麼都沒有了。'),
('f0011301-0000-0000-0000-000000000001','e0001301-0000-0000-0000-000000000001','繼續靜止，讓這個清晰延續',true,''),
('f0011302-0000-0000-0000-000000000001','e0001301-0000-0000-0000-000000000001','閉上眼睛，用其他感官感知',true,''),
('f0011303-0000-0000-0000-000000000001','e0001301-0000-0000-0000-000000000001','記錄下你看見的一切',false,'你開始在腦子裡整理，思考讓你離開了當下。那個清晰消失了，你只剩下一個普通的黑暗房間。'),
('f0011304-0000-0000-0000-000000000001','e0001301-0000-0000-0000-000000000001','往那個存在的方向移動',false,'你動了。就是這個動作，讓什麼東西察覺到你的意圖。感覺在你邁出第一步時消失了。'),
('f0011305-0000-0000-0000-000000000001','e0001301-0000-0000-0000-000000000001','出聲呼喚',false,'你的聲音讓房間裡的一切歸零。那個片刻的清晰永遠地消失了，像從來沒有存在過。'),
('f0011306-0000-0000-0000-000000000001','e0001301-0000-0000-0000-000000000001','打開手機確認時間',false,'螢幕的光刺破了黑暗。當你放下手機，那個感覺已經不在了。');
INSERT INTO story_fragments (id, story_id, layer, rarity, fragment_label, fragment_text, time_condition, weather_condition, date_condition, motif_tags, is_user_submitted)
INSERT INTO fragment_atmosphere (id, story_fragment_id, atmosphere_text) VALUES
('d0002001-0000-0000-0000-000000000001','b0000002-0000-0000-0000-000000000001','牆角有個生鏽的籠子，門沒有完全關上。籠底的木屑已經結成一塊，顏色深得像是浸過什麼液體。我不想靠近，但有某種感覺讓我停在那裡。'),
('d0002002-0000-0000-0000-000000000001','b0000002-0000-0000-0000-000000000001','那個籠子不應該還在這裡。它的金屬已經鏽到表面起皮，但底部的木屑還保持著形狀，像是什麼東西在上面蜷縮過，很久以前的事。'),
('d0002003-0000-0000-0000-000000000001','b0000002-0000-0000-0000-000000000001','我看見了那個籠子。它的門扣歪了，但門還是關著。木屑底部有一個淺淺的凹陷，圓形的，剛好是一個小動物蜷縮起來的大小。');
INSERT INTO fragment_scenes (id, story_fragment_id, layer_index, atmosphere_text, is_skippable) VALUES
('e0002101-0000-0000-0000-000000000001','b0000002-0000-0000-0000-000000000001',1,'我靠近了籠子。鏽跡從籠底蔓延到整個表面，有幾根鐵絲已經開始彎折。木屑的氣味很重，像是從未散過。',true),
('e0002102-0000-0000-0000-000000000001','b0000002-0000-0000-0000-000000000001',1,'籠子的影子在牆上拉得很長。我注意到籠底的凹陷形狀——太規則了，不像是自然形成的。',true),
('e0002103-0000-0000-0000-000000000001','b0000002-0000-0000-0000-000000000001',1,'我蹲下來和籠子齊平。門扣的金屬已經氧化成深棕色，但有一個地方被磨得光亮——像是有什麼東西反覆碰觸過那裡。',true),
('e0002201-0000-0000-0000-000000000001','b0000002-0000-0000-0000-000000000001',2,'那個氣味從籠底木屑裡滲出來，比我想的更強烈。我把手放在籠邊，感覺到了什麼——金屬比周圍的空氣稍微暖一點。',false),
('e0002202-0000-0000-0000-000000000001','b0000002-0000-0000-0000-000000000001',2,'籠門縫隙裡透出一絲什麼，太細小，我只能感覺到，無法確認是什麼。我的眼睛無法離開那個木屑的凹陷。',false),
('e0002203-0000-0000-0000-000000000001','b0000002-0000-0000-0000-000000000001',2,'我用手指輕輕碰了一下籠底的木屑。它們是硬的，壓下去沒有彈性，但在我手指接觸的瞬間，有什麼輕微的動靜。',false),
('e0002301-0000-0000-0000-000000000001','b0000002-0000-0000-0000-000000000001',3,'那個凹陷的中心還有溫度。我把手掌整個貼上去，確認了——不是錯覺。什麼東西就在這個凹陷裡待過，而且不是很久以前的事。',false),
('e0002302-0000-0000-0000-000000000001','b0000002-0000-0000-0000-000000000001',3,'我保持靜止。籠子裡什麼都沒有，但我能感覺到某種存在，像是一個剛離開的輪廓還留在空氣中。',false),
('e0002303-0000-0000-0000-000000000001','b0000002-0000-0000-0000-000000000001',3,'木屑的形狀開始讓我不安。那個凹陷太完整了，太刻意了。就像有什麼東西每天都在同一個位置蜷縮，把形狀壓進去，一天一天，直到木屑記住了它。',false);
INSERT INTO scene_options (id, scene_id, text, is_correct, fail_text) VALUES
('f0021101-0000-0000-0000-000000000001','e0002101-0000-0000-0000-000000000001','停下來，讓感知先到達',true,''),
('f0021102-0000-0000-0000-000000000001','e0002101-0000-0000-0000-000000000001','緩慢蹲下，和籠子保持同樣高度',true,''),
('f0021103-0000-0000-0000-000000000001','e0002101-0000-0000-0000-000000000001','在原地觀察，不要靠太近',true,''),
('f0021201-0000-0000-0000-000000000001','e0002201-0000-0000-0000-000000000001','保持靜止，讓那個感知繼續',true,''),
('f0021202-0000-0000-0000-000000000001','e0002201-0000-0000-0000-000000000001','輕輕把手指貼著籠底外緣',true,''),
('f0021203-0000-0000-0000-000000000001','e0002201-0000-0000-0000-000000000001','試著打開籠門',false,'金屬的聲音太突然了。你感覺到的那股溫度瞬間消失，什麼都沒有留下。'),
('f0021204-0000-0000-0000-000000000001','e0002201-0000-0000-0000-000000000001','把籠子移動位置',false,'你的動作驚動了什麼。那個重量從你手指下消失了，再也回不來。'),
('f0021205-0000-0000-0000-000000000001','e0002201-0000-0000-0000-000000000001','用指節敲一下籠子',false,'清脆的金屬聲打破了一切。空氣重新變成普通的空氣。'),
('f0021206-0000-0000-0000-000000000001','e0002201-0000-0000-0000-000000000001','拍照記錄',false,'閃光燈不該開。強光一打，你感覺到的那個存在感徹底消散了。'),
('f0021301-0000-0000-0000-000000000001','e0002301-0000-0000-0000-000000000001','把手掌完全貼合那個凹陷，靜止',true,''),
('f0021302-0000-0000-0000-000000000001','e0002301-0000-0000-0000-000000000001','閉上眼睛，只用觸覺感知',true,''),
('f0021303-0000-0000-0000-000000000001','e0002301-0000-0000-0000-000000000001','把臉湊近，想看得更清楚',false,'你湊近的動作讓你呼吸到了那裡。氣流的改變讓什麼東西察覺到了你。溫度消失了。'),
('f0021304-0000-0000-0000-000000000001','e0002301-0000-0000-0000-000000000001','試著把木屑扒開',false,'你的指尖讓木屑移動了。那個凹陷的形狀被你破壞了，什麼都結束了。'),
('f0021305-0000-0000-0000-000000000001','e0002301-0000-0000-0000-000000000001','站起來環顧四周',false,'你的視線離開了籠子。等你再回頭，那個溫度已經散了。'),
('f0021306-0000-0000-0000-000000000001','e0002301-0000-0000-0000-000000000001','叫了一聲',false,'你的聲音打破了那個瞬間。木屑的凹陷還在，但溫度已經消失了，像從來沒有存在過。');
INSERT INTO story_fragments (id, story_id, layer, rarity, fragment_label, fragment_text, time_condition, weather_condition, date_condition, motif_tags, is_user_submitted)
INSERT INTO fragment_atmosphere (id, story_fragment_id, atmosphere_text) VALUES
('d0003001-0000-0000-0000-000000000001','b0000003-0000-0000-0000-000000000001','食盆在籠子旁邊，空著，乾淨得不正常。但底部有一圈深刻的痕跡，是爪子刮出來的，刮了很多次，很用力的那種。我沒有辦法說這只是正常的進食行為。'),
('d0003002-0000-0000-0000-000000000001','b0000003-0000-0000-0000-000000000001','那個盆子空了很久了。但刮痕的分佈讓我看了很久——不是隨機的，有一個方向性，像是什麼東西在沒有食物的情況下還是一遍一遍地刮，刮到金屬見底。'),
('d0003003-0000-0000-0000-000000000001','b0000003-0000-0000-0000-000000000001','我看著那個空盆子，有種說不清楚的難受。刮痕太深了，金屬都磨薄了。這需要很長的時間，很多次，在沒有任何回報的情況下，一直刮。');
INSERT INTO fragment_scenes (id, story_fragment_id, layer_index, atmosphere_text, is_skippable) VALUES
('e0003101-0000-0000-0000-000000000001','b0000003-0000-0000-0000-000000000001',1,'我拿起了食盆。比想像中輕，幾乎沒有重量。底部的刮痕在光線下非常清晰。',true),
('e0003102-0000-0000-0000-000000000001','b0000003-0000-0000-0000-000000000001',1,'食盆底部的刮痕像是地圖，或者像是什麼東西試圖寫下什麼，但只有爪子，只有金屬，只有來回的動作。',true),
('e0003103-0000-0000-0000-000000000001','b0000003-0000-0000-0000-000000000001',1,'我把食盆翻過來。背面是乾淨的，沒有任何痕跡。只有正面——只有裡面——被刮得這樣深。',true),
('e0003201-0000-0000-0000-000000000001','b0000003-0000-0000-0000-000000000001',2,'我用手指輕輕沿著刮痕的方向移動。那個痕跡的邊緣已經氧化，時間很長了。但在中心，最深的那條，摸起來還帶著奇異的溫度。',false),
('e0003202-0000-0000-0000-000000000001','b0000003-0000-0000-0000-000000000001',2,'我把食盆放回原位，看著它。有一瞬間，我以為我聽到了什麼——非常細小的聲音，像爪子在金屬上輕輕拂過。',false),
('e0003203-0000-0000-0000-000000000001','b0000003-0000-0000-0000-000000000001',2,'刮痕在盆底呈現出一個模糊的圓形，像是一個小動物圍繞著某個中心點不斷刮動，日復一日，在空盆裡找尋什麼永遠不會出現的東西。',false),
('e0003301-0000-0000-0000-000000000001','b0000003-0000-0000-0000-000000000001',3,'我的手指停在最深的那條刮痕上。那個溫度沒有消失，反而更清晰了——不是熱，是某種殘留的能量，像是時間在這裡走得不一樣快。',false),
('e0003302-0000-0000-0000-000000000001','b0000003-0000-0000-0000-000000000001',3,'食盆開始讓我覺得沉重，不是重量，是某種意義的重量。那些刮痕不是憤怒，不是恐慌——是習慣。它還在刮，哪怕沒有食物，哪怕沒有人看見。',false),
('e0003303-0000-0000-0000-000000000001','b0000003-0000-0000-0000-000000000001',3,'我閉上眼睛，手還放在盆底。聲音回來了，比剛才更清晰——細小的，有規律的，爪子在金屬上的聲音，像心跳，像時鐘，像某種沒有終點的等待。',false);
INSERT INTO scene_options (id, scene_id, text, is_correct, fail_text) VALUES
('f0031101-0000-0000-0000-000000000001','e0003101-0000-0000-0000-000000000001','輕輕拿起食盆，感受它的重量',true,''),
('f0031102-0000-0000-0000-000000000001','e0003101-0000-0000-0000-000000000001','蹲下來，在它原來的位置看它',true,''),
('f0031103-0000-0000-0000-000000000001','e0003101-0000-0000-0000-000000000001','先不要動，只是看',true,''),
('f0031201-0000-0000-0000-000000000001','e0003201-0000-0000-0000-000000000001','用指尖沿刮痕慢慢移動，保持安靜',true,''),
('f0031202-0000-0000-0000-000000000001','e0003201-0000-0000-0000-000000000001','把食盆放回去，靜靜等待',true,''),
('f0031203-0000-0000-0000-000000000001','e0003201-0000-0000-0000-000000000001','用力按壓刮痕，想確認溫度',false,'你的力道太重了。那個細微的溫度在你按下去的瞬間消失了。'),
('f0031204-0000-0000-0000-000000000001','e0003201-0000-0000-0000-000000000001','把食盆放進包包',false,'你的意圖破壞了什麼。就在你準備拿走的那一刻，食盆恢復了普通物品的感覺，只是舊的、生鏽的、空的。'),
('f0031205-0000-0000-0000-000000000001','e0003201-0000-0000-0000-000000000001','用力搖晃食盆',false,'聲響打破了一切。什麼東西在巨響中消失了，不會回來。'),
('f0031206-0000-0000-0000-000000000001','e0003201-0000-0000-0000-000000000001','對著食盆說話',false,'你的聲音太大了。那個若有似無的聲音被你的話語蓋過，再也聽不見了。'),
('f0031301-0000-0000-0000-000000000001','e0003301-0000-0000-0000-000000000001','保持靜止，讓感知繼續延伸',true,''),
('f0031302-0000-0000-0000-000000000001','e0003301-0000-0000-0000-000000000001','閉眼，把注意力完全放在觸感上',true,''),
('f0031303-0000-0000-0000-000000000001','e0003301-0000-0000-0000-000000000001','開燈，想看得更清楚',false,'燈光讓一切變得過於真實。那個模糊但真實的感知消失了，只剩下一個舊食盆的刮痕。'),
('f0031304-0000-0000-0000-000000000001','e0003301-0000-0000-0000-000000000001','把食盆翻面',false,'物品的方向改變了什麼。你翻過去的瞬間，那個溫度消失了，再沒回來。'),
('f0031305-0000-0000-0000-000000000001','e0003301-0000-0000-0000-000000000001','站起來，換個角度看',false,'你移動了。那個聲音在你站起來的瞬間消失了，只剩下靜默。'),
('f0031306-0000-0000-0000-000000000001','e0003301-0000-0000-0000-000000000001','試著往食盆裡放東西',false,'你帶進去的東西中斷了什麼。那個存在感在你動作的同時消散了。');
INSERT INTO story_fragments (id, story_id, layer, rarity, fragment_label, fragment_text, time_condition, weather_condition, date_condition, motif_tags, is_user_submitted)
INSERT INTO fragment_atmosphere (id, story_fragment_id, atmosphere_text) VALUES
('d0004001-0000-0000-0000-000000000001','b0000004-0000-0000-0000-000000000001','門邊有張便條紙。已經泛黃，邊角翹起來，膠帶早就乾掉了，卻還粘在那裡，像是有什麼東西讓它不會掉下來。字跡模糊了，但我認出了其中幾個字——「我會回來」。'),
('d0004002-0000-0000-0000-000000000001','b0000004-0000-0000-0000-000000000001','那張便條紙的顏色和牆壁幾乎一樣黃了。它貼在那裡的時間太長了，久到我不知道到底是紙黃了還是牆黃了。但字跡還在，稀薄的，像是快要消失卻還沒有完全消失。'),
('d0004003-0000-0000-0000-000000000001','b0000004-0000-0000-0000-000000000001','我看見了那張便條紙的時候，有一種奇異的感覺——像是它一直在等被看見。紙張泛黃，墨跡模糊，但某種意圖還在，穿過時間，還在試圖傳達什麼。');
INSERT INTO fragment_scenes (id, story_fragment_id, layer_index, atmosphere_text, is_skippable) VALUES
('e0004101-0000-0000-0000-000000000001','b0000004-0000-0000-0000-000000000001',1,'我靠近了便條紙。紙張已經乾透，觸感會是粗糙的，我還沒碰就知道。字跡的方向是向上的，是有人刻意寫給門口進來的人看的。',true),
('e0004102-0000-0000-0000-000000000001','b0000004-0000-0000-0000-000000000001',1,'便條紙的左下角有個污點，像是什麼液體乾掉之後留下的印記。字跡在那個位置特別模糊，但我猜那幾個字是最重要的。',true),
('e0004103-0000-0000-0000-000000000001','b0000004-0000-0000-0000-000000000001',1,'我用眼角看那張便條紙的時候，覺得字跡好像比直視時清晰一點。我試了幾次，確認了——不看它的時候，反而更能感知它的內容。',true),
('e0004201-0000-0000-0000-000000000001','b0000004-0000-0000-0000-000000000001',2,'我慢慢把臉湊近。墨跡已經褪色，但留下的壓痕還在——那是用力寫下去的，每一個字都很用力，像是要讓紙張記住。',false),
('e0004202-0000-0000-0000-000000000001','b0000004-0000-0000-0000-000000000001',2,'便條紙的氣味——紙的、膠帶的、時間的——全部混在一起。我閉上眼睛，試著用氣味感知，有什麼東西在這個混合裡還沒有完全消散。',false),
('e0004203-0000-0000-0000-000000000001','b0000004-0000-0000-0000-000000000001',2,'字跡的一部分我可以辨認。「豆豆」——這是名字，是有人對著這個方向、對著這個地方說的名字，留下來，等被聽見。',false),
('e0004301-0000-0000-0000-000000000001','b0000004-0000-0000-0000-000000000001',3,'我的手指輕輕貼著便條紙的邊緣，沒有碰到字跡，只是感受那個紙張的質地和溫度。有什麼從紙裡滲出來，不是資訊，是情緒，積累了很久的那種。',false),
('e0004302-0000-0000-0000-000000000001','b0000004-0000-0000-0000-000000000001',3,'那幾個字——「我會回來看你」——我認出了更多。在光線最好的角度，最後四個字非常清晰。那個承諾留在這裡，沒有人兌現，但也沒有人來撕掉它。',false),
('e0004303-0000-0000-0000-000000000001','b0000004-0000-0000-0000-000000000001',3,'便條紙微微地動了一下。沒有風，但它動了，幅度極小，像是呼吸，或者像是有什麼從裡面輕輕地推了一下，然後放棄了。',false);
INSERT INTO scene_options (id, scene_id, text, is_correct, fail_text) VALUES
('f0041101-0000-0000-0000-000000000001','e0004101-0000-0000-0000-000000000001','停下來，在距離外先看',true,''),
('f0041102-0000-0000-0000-000000000001','e0004101-0000-0000-0000-000000000001','側身觀察，用眼角感知',true,''),
('f0041103-0000-0000-0000-000000000001','e0004101-0000-0000-0000-000000000001','往後退一步，讓自己看到全局',true,''),
('f0041201-0000-0000-0000-000000000001','e0004201-0000-0000-0000-000000000001','俯身靠近，保持靜止，用眼睛慢慢辨認',true,''),
('f0041202-0000-0000-0000-000000000001','e0004201-0000-0000-0000-000000000001','閉眼，只用氣味和感覺',true,''),
('f0041203-0000-0000-0000-000000000001','e0004201-0000-0000-0000-000000000001','把便條紙揭下來，拿近點看',false,'你把它揭下來的瞬間，什麼改變了。它只是一張舊便條，字跡模糊，不再有任何重量。'),
('f0041204-0000-0000-0000-000000000001','e0004201-0000-0000-0000-000000000001','用手機拍下來，放大看',false,'螢幕的光介入了。便條紙在鏡頭裡變成了一個普通的物件，那個感知從螢幕後面消失了。'),
('f0041205-0000-0000-0000-000000000001','e0004201-0000-0000-0000-000000000001','大聲讀出你看得懂的字',false,'聲音把它變成了資訊。那個模糊又真實的感知在你開口的瞬間消失，剩下的只是幾個字。'),
('f0041206-0000-0000-0000-000000000001','e0004201-0000-0000-0000-000000000001','試著把字跡描清楚',false,'你的筆觸覆蓋在舊墨跡上。什麼結束了，你不確定是什麼，但你知道結束了。'),
('f0041301-0000-0000-0000-000000000001','e0004301-0000-0000-0000-000000000001','維持輕觸，靜靜感受',true,''),
('f0041302-0000-0000-0000-000000000001','e0004301-0000-0000-0000-000000000001','閉眼，讓那個情緒自然地到來',true,''),
('f0041303-0000-0000-0000-000000000001','e0004301-0000-0000-0000-000000000001','把便條紙整個蓋住，用手掌壓住',false,'你的動作太大了。那個細微的動靜在你壓下去的瞬間消失，什麼都結束了。'),
('f0041304-0000-0000-0000-000000000001','e0004301-0000-0000-0000-000000000001','把它從牆上取下',false,'它離開了原來的位置。就是這樣，那個與地方的連結斷了，再也拿不回來。'),
('f0041305-0000-0000-0000-000000000001','e0004301-0000-0000-0000-000000000001','往後退，不想感受那個情緒',false,'你退開了。距離讓一切回到了正常，那個感知消失了，你安全了，但也失去了。'),
('f0041306-0000-0000-0000-000000000001','e0004301-0000-0000-0000-000000000001','叫了一聲人名',false,'你說出的名字打破了那個沉默。便條紙不再動了，空氣重新變成普通的空氣。');
INSERT INTO story_fragments (id, story_id, layer, rarity, fragment_label, fragment_text, time_condition, weather_condition, date_condition, motif_tags, is_user_submitted)
INSERT INTO fragment_atmosphere (id, story_fragment_id, atmosphere_text) VALUES
('d0005001-0000-0000-0000-000000000001','b0000005-0000-0000-0000-000000000001','地板上有爪印。非常細小，我差點沒看見——不是因為它輕，而是因為太習慣地板是乾淨的。我蹲下來，用手機光源以斜角打過去，確認了：是爪印，從牆角開始，往走廊深處延伸。'),
('d0005002-0000-0000-0000-000000000001','b0000005-0000-0000-0000-000000000001','我不知道從什麼時候開始注意到那條線。地板上很淺的痕跡，像是有什麼非常輕的東西走過，每一個落點都極小。往前走，往黑暗裡走，沒有回頭的跡象。'),
('d0005003-0000-0000-0000-000000000001','b0000005-0000-0000-0000-000000000001','那些爪印的間距非常規律。我用手指量了一下——每一步的距離幾乎完全相同，像是機械的，或者像是一個非常平靜的動物，用完全一樣的節奏，一步一步往前走。往不知道哪裡走。');
INSERT INTO fragment_scenes (id, story_fragment_id, layer_index, atmosphere_text, is_skippable) VALUES
('e0005101-0000-0000-0000-000000000001','b0000005-0000-0000-0000-000000000001',1,'我跟著爪印往前走。光線越來越少，但爪印還在——每一個都清晰，好像是剛留下的，但地板的灰塵告訴我不是。',true),
('e0005102-0000-0000-0000-000000000001','b0000005-0000-0000-0000-000000000001',1,'爪印在某個地方改變了方向。不是急轉，是一個緩慢的弧度，像是有什麼東西停下來，調整了一下方向，然後繼續走。非常平靜的轉向。',true),
('e0005103-0000-0000-0000-000000000001','b0000005-0000-0000-0000-000000000001',1,'我用手機的光線以最低角度掃過地板。爪印在光線裡變得非常清晰——四個細小的點，有一定的排列邏輯，每一步都一樣深。',true),
('e0005201-0000-0000-0000-000000000001','b0000005-0000-0000-0000-000000000001',2,'爪印在我腳邊停了。最後一個印子就在距離我大概一步的地方，然後沒有了。消失的地方沒有牆壁，沒有任何阻隔，爪印就這樣結束了，像是什麼東西在這個位置停下來，然後消失在了地板裡。',false),
('e0005202-0000-0000-0000-000000000001','b0000005-0000-0000-0000-000000000001',2,'我把手放到最後一個爪印上。地板是涼的，但那個位置——就那一個點——稍微暖一點，像是剛剛才有什麼東西在這裡。',false),
('e0005203-0000-0000-0000-000000000001','b0000005-0000-0000-0000-000000000001',2,'那個溫度從地板傳到我的手心。我感覺到了什麼——不是聲音，不是視覺，是某種方向感。有什麼東西在我前方不遠的黑暗裡，靜止著，等待著。',false),
('e0005301-0000-0000-0000-000000000001','b0000005-0000-0000-0000-000000000001',3,'黑暗的前方，有什麼東西在那裡。我感知到了，不是看見，是感知到了一個存在，非常小，非常靜，像一個等待變成了固體。',false),
('e0005302-0000-0000-0000-000000000001','b0000005-0000-0000-0000-000000000001',3,'我的手還貼著地板。爪印的終點傳來的溫度越來越清晰。那個方向感越來越強——某個東西在黑暗裡，知道我在這裡，也讓我知道它在那裡。這不是威脅，只是一個事實的確認：我們都在這裡。',false),
('e0005303-0000-0000-0000-000000000001','b0000005-0000-0000-0000-000000000001',3,'我屏住了呼吸。在我完全靜止的那一刻，我聽到了——非常輕，極細小，但確實存在——爪子在地板上移動的聲音，從我的前方開始，緩緩往我的方向靠近，然後停了。就在我面前，停了。',false);
INSERT INTO scene_options (id, scene_id, text, is_correct, fail_text) VALUES
('f0051101-0000-0000-0000-000000000001','e0005101-0000-0000-0000-000000000001','緩慢地跟著爪印的方向移動',true,''),
('f0051102-0000-0000-0000-000000000001','e0005101-0000-0000-0000-000000000001','蹲下來，從低角度觀察',true,''),
('f0051103-0000-0000-0000-000000000001','e0005101-0000-0000-0000-000000000001','先停在原地，看爪印延伸的整體路徑',true,''),
('f0051201-0000-0000-0000-000000000001','e0005201-0000-0000-0000-000000000001','把手輕輕放在最後一個爪印上，靜止',true,''),
('f0051202-0000-0000-0000-000000000001','e0005201-0000-0000-0000-000000000001','在爪印消失的位置蹲下，閉眼感知方向',true,''),
('f0051203-0000-0000-0000-000000000001','e0005201-0000-0000-0000-000000000001','打開手機手電筒，往前照',false,'強光破壞了那個平衡。黑暗裡的什麼東西在你打開燈的同時消失了，不會回來。'),
('f0051204-0000-0000-0000-000000000001','e0005201-0000-0000-0000-000000000001','大步往黑暗裡走',false,'你的動作太大太快。那個安靜的存在感在你走出第一步的瞬間消散了，地板只剩地板。'),
('f0051205-0000-0000-0000-000000000001','e0005201-0000-0000-0000-000000000001','往回走，離開爪印',false,'你選擇離開了。方向感隨著距離消失，你安全地回到了入口，什麼都沒有帶走。'),
('f0051206-0000-0000-0000-000000000001','e0005201-0000-0000-0000-000000000001','用腳踩上爪印',false,'你踩上去了。那個地板的溫度在你的重量之下立刻消失，什麼都結束了。'),
('f0051301-0000-0000-0000-000000000001','e0005301-0000-0000-0000-000000000001','完全靜止，讓那個存在感自己靠近',true,''),
('f0051302-0000-0000-0000-000000000001','e0005301-0000-0000-0000-000000000001','閉眼，只用聽覺和觸覺',true,''),
('f0051303-0000-0000-0000-000000000001','e0005301-0000-0000-0000-000000000001','用手電筒直接照向那個方向',false,'光線打進黑暗。那個停在你面前的存在消失了，只剩下普通的黑暗和地板。'),
('f0051304-0000-0000-0000-000000000001','e0005301-0000-0000-0000-000000000001','伸手往前探',false,'你的手臂伸出去了。那個停下來的東西在你的動作裡消失了，爪印的溫度也跟著消散。'),
('f0051305-0000-0000-0000-000000000001','e0005301-0000-0000-0000-000000000001','說話',false,'你的聲音充滿了這個空間。停在你面前的存在退走了，這次是真的走了，沒有留下任何聲音。'),
('f0051306-0000-0000-0000-000000000001','e0005301-0000-0000-0000-000000000001','後退離開',false,'你退了。那個靠近你的聲音停止了，你感覺它也退開了，然後消失了。你們就這樣分開了。');
INSERT INTO story_fragments (id, story_id, layer, rarity, fragment_label, fragment_text, time_condition, weather_condition, date_condition, motif_tags, is_user_submitted)
INSERT INTO fragment_atmosphere (id, story_fragment_id, atmosphere_text) VALUES
('d0l01001-0000-0000-0000-000000000001','c0000001-0000-0000-0000-000000000001','走廊的燈壞了一半。我走到一半，看見盡頭有個東西停著。不大，大概一隻手掌的大小。毛色是灰白的，幾乎和牆壁融在一起。然後我看見了它的眼睛——兩個極小的光點，直視著我，一動也不動。'),
('d0l01002-0000-0000-0000-000000000001','c0000001-0000-0000-0000-000000000001','我以為是光線的問題。但那個東西確實在那裡，停在走廊盡頭的地板上。體型很小，但存在感異常地重。它沒有逃，只是看著我，像在等什麼。'),
('d0l01003-0000-0000-0000-000000000001','c0000001-0000-0000-0000-000000000001','深夜的走廊很安靜。我聽見自己的呼吸聲。然後我看見牆角有個東西，毛是灰白的，幾近透明。它轉過頭來，眼窩裡有冷光。我和它對視了大概三秒，然後它消失了。');
INSERT INTO fragment_scenes (id, story_fragment_id, layer_index, atmosphere_text, is_skippable) VALUES
('e0l01101-0000-0000-0000-000000000001','c0000001-0000-0000-0000-000000000001',1,'我在走廊中央停下來。那個東西也停著。我們之間大概有五公尺。它的眼睛一直看著我，沒有眨眼，那兩個光點平靜得讓我背脊發涼。',false),
('e0l01102-0000-0000-0000-000000000001','c0000001-0000-0000-0000-000000000001',1,'走廊很窄。那個東西堵在我必須經過的路上，但它沒有任何攻擊的姿態，只是站著，用那兩個發光的眼窩看著我。',false),
('e0l01103-0000-0000-0000-000000000001','c0000001-0000-0000-0000-000000000001',1,'我的手機在口袋裡。我想拍下它，但某種直覺告訴我不要有任何多餘的動作。它太平靜了，平靜得像在等我做出第一個錯誤的決定。',false),
('e0l01201-0000-0000-0000-000000000001','c0000001-0000-0000-0000-000000000001',2,'它開始移動了。不是朝我，是側身，沿著牆根緩緩走。爪子踩在地板上沒有聲音。牠的毛在走廊昏黃的燈光下幾乎是透明的。',false),
('e0l01202-0000-0000-0000-000000000001','c0000001-0000-0000-0000-000000000001',2,'我蹲著，它也蹲著。我們之間的距離縮短了一點，但不是因為我動了。是它主動靠近了一步，然後停下來，繼續看著我。',false),
('e0l01203-0000-0000-0000-000000000001','c0000001-0000-0000-0000-000000000001',2,'它把頭歪了一下，像在辨認什麼。那個動作非常像活的動物，又不完全是。然後它發出一個極輕的聲音，我幾乎以為自己聽錯了。',false),
('e0l01301-0000-0000-0000-000000000001','c0000001-0000-0000-0000-000000000001',3,'它停下來了，就在我面前大概一公尺的地方。我可以清楚地看見它——灰白的毛，幾近透明，眼窩深陷，裡面的冷光在黑暗中很穩定。它不像在威脅我，更像是在等待什麼。',false),
('e0l01302-0000-0000-0000-000000000001','c0000001-0000-0000-0000-000000000001',3,'我看見了它的爪子。很小，形狀和活的動物一樣，但踩在地板上完全沒有聲音。它低下頭，嗅了一下空氣，然後再次抬起頭看我。那兩個光點從未移開過我的方向。',false),
('e0l01303-0000-0000-0000-000000000001','c0000001-0000-0000-0000-000000000001',3,'我們就這樣對視著。它的存在感很重，但沒有惡意。我突然明白了——它在找什麼人，而我讓它想起了那個人。這個認知讓我背脊發涼，遠比看見它本身更讓我恐懼。',false);
INSERT INTO scene_options (id, scene_id, text, is_correct, fail_text) VALUES
('f0l1101-0000-0000-0000-000000000001','e0l01101-0000-0000-0000-000000000001','放慢呼吸，保持靜止，和它對視',true,''),
('f0l1102-0000-0000-0000-000000000001','e0l01101-0000-0000-0000-000000000001','極緩慢地蹲下，讓自己和它視線齊平',true,''),
('f0l1103-0000-0000-0000-000000000001','e0l01101-0000-0000-0000-000000000001','打開手機手電筒照向它',false,'強光照過去。那兩個光點消失了。走廊盡頭只剩空地板。'),
('f0l1104-0000-0000-0000-000000000001','e0l01101-0000-0000-0000-000000000001','發出聲音，試探它的反應',false,'你的聲音在走廊裡迴響。那個東西在你說完第一個字之前就消失了。'),
('f0l1105-0000-0000-0000-000000000001','e0l01101-0000-0000-0000-000000000001','退後一步',false,'你一動，它消失了。走廊恢復安靜，像什麼都沒有發生過。'),
('f0l1201-0000-0000-0000-000000000001','e0l01201-0000-0000-0000-000000000001','繼續靜止，讓它自己決定下一步',true,''),
('f0l1202-0000-0000-0000-000000000001','e0l01201-0000-0000-0000-000000000001','非常緩慢地把手放到地板上，掌心向上',true,''),
('f0l1203-0000-0000-0000-000000000001','e0l01201-0000-0000-0000-000000000001','跟著它移動的方向轉身',false,'你動了。它在你轉身的瞬間消失了，什麼都沒有留下。'),
('f0l1204-0000-0000-0000-000000000001','e0l01201-0000-0000-0000-000000000001','伸手想要碰觸它',false,'你的手伸出去，它後退了一步，然後消失在牆壁裡。'),
('f0l1205-0000-0000-0000-000000000001','e0l01201-0000-0000-0000-000000000001','站起來',false,'你一站起來，它消失了。走廊又變成一條普通的走廊。'),
('f0l1206-0000-0000-0000-000000000001','e0l01201-0000-0000-0000-000000000001','拿出手機想拍下它',false,'螢幕亮起來。等你對好焦，那個位置已經空了。'),
('f0l1301-0000-0000-0000-000000000001','e0l01301-0000-0000-0000-000000000001','閉上眼睛，讓它做決定',true,''),
('f0l1302-0000-0000-0000-000000000001','e0l01301-0000-0000-0000-000000000001','維持對視，緩慢地、有意識地呼吸',true,''),
('f0l1303-0000-0000-0000-000000000001','e0l01301-0000-0000-0000-000000000001','開口對它說話',false,'你說了一個字。它在聲音出口的瞬間消失了，只留下一個極輕的氣味，像是木屑。'),
('f0l1304-0000-0000-0000-000000000001','e0l01301-0000-0000-0000-000000000001','站起來，讓它看清楚你',false,'你動了。它後退了一步，那兩個光點在你完全站直之前就熄滅了。'),
('f0l1305-0000-0000-0000-000000000001','e0l01301-0000-0000-0000-000000000001','把視線移開，假裝沒有看見它',false,'你的視線離開了它。等你再看回去，那個位置已經空了。它不喜歡被忽視。'),
('f0l1306-0000-0000-0000-000000000001','e0l01301-0000-0000-0000-000000000001','緩慢地後退',false,'你退了一步。它看著你退，然後消失了。');
INSERT INTO story_fragments (id, story_id, layer, rarity, fragment_label, fragment_text, time_condition, weather_condition, date_condition, motif_tags, is_user_submitted)
INSERT INTO fragment_atmosphere (id, story_fragment_id, atmosphere_text) VALUES
('d0l02001-0000-0000-0000-000000000001','c0000002-0000-0000-0000-000000000001','我快要睡著的時候看到的。房間的黑暗裡，床腳那個方向，有兩個很小很小的光點。我以為是手機的反光，但手機是關著的。等我更仔細看的時候，它們消失了。'),
('d0l02002-0000-0000-0000-000000000001','c0000002-0000-0000-0000-000000000001','深夜，介於清醒和睡著之間的那個狀態。我感覺到床腳有什麼東西的存在，不是聽到，是感覺到——某種重量，某種凝視，非常輕，但確實在那裡。'),
('d0l02003-0000-0000-0000-000000000001','c0000002-0000-0000-0000-000000000001','睡前，我習慣把燈全關。在完全黑暗裡，我的眼睛需要幾分鐘才能適應。適應之後，我看見了——床腳邊，地板上，有個東西蜷縮著，一動也不動，它的眼窩裡有光。');
INSERT INTO fragment_scenes (id, story_fragment_id, layer_index, atmosphere_text, is_skippable) VALUES
('e0l02101-0000-0000-0000-000000000001','c0000002-0000-0000-0000-000000000001',1,'我慢慢坐起來，但沒有開燈。那兩個光點還在，離我很近，就在床腳邊的地板上。它的輪廓在黑暗裡隱約可見，很小，蜷縮著。',false),
('e0l02102-0000-0000-0000-000000000001','c0000002-0000-0000-0000-000000000001','我保持躺著，只是轉頭。那個東西在床腳靜靜地坐著，眼窩的光很穩定，像兩顆很小很小的星。它的存在讓這個房間感覺不一樣了，但我說不清楚哪裡不一樣。',false),
('e0l02103-0000-0000-0000-000000000001','c0000002-0000-0000-0000-000000000001','那兩個光點沒有移動。它一直在那個位置，看著我。不是盯著，是陪著。某種區別我說不清楚，但感覺得出來。',false),
('e0l02201-0000-0000-0000-000000000001','c0000002-0000-0000-0000-000000000001','它靠近了一點。我看見了它的輪廓更清楚了——灰白的，很小，毛的邊緣幾近透明。它在床腳的木板邊緣停下來，頭稍微低著，像是在等什麼。',false),
('e0l02202-0000-0000-0000-000000000001','c0000002-0000-0000-0000-000000000001','那個東西發出了一個聲音——極輕，幾乎不是聲音，是某種氣息的移動。然後停了。然後又來了一次，像是在嘗試什麼，或者在說什麼。',false),
('e0l02203-0000-0000-0000-000000000001','c0000002-0000-0000-0000-000000000001','它繞著床腳走了一圈。沒有聲音，只有那兩個光點移動的軌跡。走完一圈之後，它回到了原來的位置，繼續看著我。那個眼神讓我難以描述：不是害怕，是一種非常久的等待。',false),
('e0l02301-0000-0000-0000-000000000001','c0000002-0000-0000-0000-000000000001','它跳上床了。輕到幾乎沒有重量感，只有極微小的震動。它走到我腳邊，蜷縮下來。兩個光點還是看著我，但不知道從什麼時候開始，那個目光讓我想到的不是恐懼，而是某種極度漫長的等待終於有了回應。',false),
('e0l02302-0000-0000-0000-000000000001','c0000002-0000-0000-0000-000000000001','它在我腳邊完全靜下來了。我感覺到它的重量——很輕，幾乎感覺不到，但確實在那裡。那兩個光點緩緩地閉上了，然後再睜開，像是在確認什麼。',false),
('e0l02303-0000-0000-0000-000000000001','c0000002-0000-0000-0000-000000000001','它就這樣在我腳邊蜷縮著，不動。我也不動。在那個完全靜止的時刻，我理解了——它不是來找我的。它只是需要一個地方，在某個人睡著之前，蜷縮在那裡，等一個不會來的人。',false);
INSERT INTO scene_options (id, scene_id, text, is_correct, fail_text) VALUES
('f0l2101-0000-0000-0000-000000000001','e0l02101-0000-0000-0000-000000000001','保持躺著，讓眼睛繼續適應黑暗',true,''),
('f0l2102-0000-0000-0000-000000000001','e0l02101-0000-0000-0000-000000000001','緩慢坐起，不要開燈',true,''),
('f0l2103-0000-0000-0000-000000000001','e0l02101-0000-0000-0000-000000000001','開燈',false,'光線充滿了房間。那兩個光點消失了，地板上什麼都沒有。'),
('f0l2104-0000-0000-0000-000000000001','e0l02101-0000-0000-0000-000000000001','大聲說話或叫出聲',false,'你的聲音打破了那個靜默。那兩個光點在你開口的瞬間消失，房間恢復了普通。'),
('f0l2105-0000-0000-0000-000000000001','e0l02101-0000-0000-0000-000000000001','用腳踢一下',false,'你的腳踢出去。那個東西消失了，比你的動作還快，沒有留下任何痕跡。'),
('f0l2201-0000-0000-0000-000000000001','e0l02201-0000-0000-0000-000000000001','靜止，讓它按自己的節奏靠近',true,''),
('f0l2202-0000-0000-0000-000000000001','e0l02201-0000-0000-0000-000000000001','把手輕輕垂在床邊，掌心向下',true,''),
('f0l2203-0000-0000-0000-000000000001','e0l02201-0000-0000-0000-000000000001','用手電筒照',false,'強光讓它消失了。地板上什麼都沒有。'),
('f0l2204-0000-0000-0000-000000000001','e0l02201-0000-0000-0000-000000000001','往床腳伸手',false,'你的手伸出去了。它在你手觸碰空氣的瞬間後退，然後消失了。'),
('f0l2205-0000-0000-0000-000000000001','e0l02201-0000-0000-0000-000000000001','翻身背對它',false,'你轉身了。那種存在感慢慢消失了，等你再轉回來，什麼都不在了。'),
('f0l2206-0000-0000-0000-000000000001','e0l02201-0000-0000-0000-000000000001','拿起旁邊的東西',false,'你的動作太大。它消失在你伸手的瞬間，再沒回來。'),
('f0l2301-0000-0000-0000-000000000001','e0l02301-0000-0000-0000-000000000001','完全靜止，讓它留在那裡',true,''),
('f0l2302-0000-0000-0000-000000000001','e0l02301-0000-0000-0000-000000000001','閉上眼睛，專注感受那個極輕的重量',true,''),
('f0l2303-0000-0000-0000-000000000001','e0l02301-0000-0000-0000-000000000001','開燈，想看清楚',false,'光線一亮，那個重量消失了。床腳空空的，什麼都沒有。'),
('f0l2304-0000-0000-0000-000000000001','e0l02301-0000-0000-0000-000000000001','試著碰觸它',false,'你的手指碰到的是空氣。它在你伸手的瞬間消失，那個極輕的重量消散了。'),
('f0l2305-0000-0000-0000-000000000001','e0l02301-0000-0000-0000-000000000001','起床走動',false,'你一移動，那個重量消失了。牠走了，你說不清楚往哪裡走，但你知道牠走了。'),
('f0l2306-0000-0000-0000-000000000001','e0l02301-0000-0000-0000-000000000001','說出一個名字',false,'你說的名字讓它警覺了。那個光點在你說完之前就熄滅了，床腳空了，只剩黑暗。');
